     1	/** Every failure the gateway can describe to a client; anything else is a bug. */
     2	export type GatewayErrorKind =
     3	  | "bad-target" // the URL names no contract
     4	  | "unknown-chain" // no RPC endpoint is configured for the chain
     5	  | "not-found" // the contract answered, and the answer is "no such resource"
     6	  | "bad-response" // the contract or the RPC returned bytes that do not decode
     7	  | "upstream"; // no configured RPC endpoint produced an answer
     8	
     9	const STATUS: Record<GatewayErrorKind, number> = {
    10	  "bad-target": 400,
    11	  "unknown-chain": 404,
    12	  "not-found": 404,
    13	  "bad-response": 502,
    14	  upstream: 502,
    15	};
    16	
    17	export class GatewayError extends Error {
    18	  readonly kind: GatewayErrorKind;
    19	
    20	  constructor(kind: GatewayErrorKind, message: string) {
    21	    super(message);
    22	    this.name = "GatewayError";
    23	    this.kind = kind;
    24	  }
    25	
    26	  get status(): number {
    27	    return STATUS[this.kind];
    28	  }
    29	}
