     1	import { HTML_SELECTOR, decodeRequestResult, decodeString, encodeRequest } from "./abi.ts";
     2	import { GatewayError } from "./errors.ts";
     3	import { type GatewayResponse, type Rpc, RpcRevert } from "./ports.ts";
     4	import type { Target } from "./target.ts";
     5	
     6	/**
     7	 * Headers a contract may set on its own response. An allowlist, because the same core runs behind
     8	 * adapters where a contract-chosen `Set-Cookie` or `Clear-Site-Data` would reach past its origin.
     9	 */
    10	const PASSED_HEADERS = new Set([
    11	  "content-type",
    12	  "content-language",
    13	  "content-disposition",
    14	  "content-security-policy",
    15	  "referrer-policy",
    16	  "permissions-policy",
    17	  "cross-origin-opener-policy",
    18	  "cross-origin-embedder-policy",
    19	  "cross-origin-resource-policy",
    20	  "access-control-allow-origin",
    21	  "x-frame-options",
    22	]);
    23	
    24	/** Never cached below the client, and never sniffed into a type the contract did not declare. */
    25	const FIXED_HEADERS: [string, string][] = [
    26	  ["cache-control", "no-store"],
    27	  ["x-content-type-options", "nosniff"],
    28	];
    29	
    30	const HEADER_VALUE = /^[\t\x20-\x7e]*$/;
    31	
    32	function respond(status: number, type: string, body: Uint8Array, extra: [string, string][] = []): GatewayResponse {
    33	  return { status, headers: [["content-type", type], ...extra, ...FIXED_HEADERS], body };
    34	}
    35	
    36	/** Plain text, always: an error body never carries markup built from a URL or a contract. */
    37	export function errorResponse(error: unknown): GatewayResponse {
    38	  const known = error instanceof GatewayError ? error : new GatewayError("upstream", "internal gateway error");
    39	  const body = new TextEncoder().encode(`gw44: ${known.message}\n`);
    40	  return respond(known.status, "text/plain; charset=utf-8", body);
    41	}
    42	
    43	/** An address with no code, or a fallback that returns nothing, answers a call with zero bytes. */
    44	async function call(target: Target, rpc: Rpc, data: string): Promise<Uint8Array> {
    45	  const out = await rpc.call(target.chain, target.address, data);
    46	  if (out.length === 0) throw new GatewayError("not-found", "the address does not serve this resource");
    47	  return out;
    48	}
    49	
    50	async function html(target: Target, rpc: Rpc): Promise<GatewayResponse> {
    51	  const body = decodeString(await call(target, rpc, HTML_SELECTOR));
    52	  if (body.length === 0) throw new GatewayError("not-found", "html() returned an empty document");
    53	  return respond(200, "text/html; charset=utf-8", body);
    54	}
    55	
    56	async function request(target: Target, rpc: Rpc): Promise<GatewayResponse> {
    57	  const data = await call(target, rpc, encodeRequest(target.resource, target.params));
    58	  const result = decodeRequestResult(data);
    59	  // The range a `Response` can be built with; 1xx and 3xx-without-Location are not documents.
    60	  if (result.status < 200 || result.status > 599) {
    61	    throw new GatewayError("bad-response", `contract returned status ${result.status}`);
    62	  }
    63	  let type = "application/octet-stream";
    64	  const extra: [string, string][] = [];
    65	  for (const [rawKey, value] of result.headers) {
    66	    const key = rawKey.toLowerCase();
    67	    // A synthesized response is not content-decoded by the browser; garbage is worse than a 502.
    68	    if (key === "content-encoding" && value.toLowerCase() !== "identity") {
    69	      throw new GatewayError("bad-response", `content-encoding ${value} is not supported`);
    70	    }
    71	    if (!PASSED_HEADERS.has(key) || !HEADER_VALUE.test(value)) continue;
    72	    if (key === "content-type") type = value;
    73	    else extra.push([key, value]);
    74	  }
    75	  const nullBody = result.status === 204 || result.status === 205 || result.status === 304;
    76	  return respond(result.status, type, nullBody ? new Uint8Array() : result.body, extra);
    77	}
    78	
    79	/**
    80	 * The whole gateway: the root is ERC-8244 `html()`, every other path is ERC-5219 `request()`.
    81	 * Never throws; a failure is a response.
    82	 */
    83	export async function resolve(target: Target, rpc: Rpc): Promise<GatewayResponse> {
    84	  try {
    85	    if (!rpc.supports(target.chain)) {
    86	      throw new GatewayError("unknown-chain", `chain ${target.chain} is not configured on this gateway`);
    87	    }
    88	    return await (target.resource.length === 0 ? html(target, rpc) : request(target, rpc));
    89	  } catch (error) {
    90	    if (error instanceof RpcRevert) {
    91	      return errorResponse(new GatewayError("not-found", "the contract does not serve this resource"));
    92	    }
    93	    return errorResponse(error);
    94	  }
    95	}
