    83	  const address = rawAddress?.toLowerCase();
    84	  if (chain === undefined || address === undefined) return null;
    85	  if (!CHAIN.test(chain) || !ADDRESS.test(address)) return null;
    86	  const target: Target = { chain, address, resource: trimRoot(rest), params };
