   100	  }
   101	  const address = rawAddress.toLowerCase();
   102	  if (!CHAIN.test(chain)) {
   103	    throw new GatewayError("bad-target", `pin chain must be a decimal chain id; got ${JSON.stringify(chain)}`);
   104	  }
   105	  if (!ADDRESS.test(address)) {
   106	    throw new GatewayError("bad-target", `pin address must be 0x and 40 hex digits; got ${JSON.stringify(rawAddress)}`);
   107	  }
   108	  return { default: chain, contracts: { [chain]: address } };
   109	}
   110	
   111	/**
   112	 * The configuration file, validated. Throws rather than returning null for the same reason
   113	 * `parsePin` does: a malformed configuration is a mistake, not a URL that names no contract.
   114	 */
   115	export function parsePins(value: unknown): Pins {
