   126	  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
   127	    throw new GatewayError("bad-target", `configuration "contracts" must be an object; got ${describe(raw)}`);
   128	  }
   129	  const contracts: Record<string, string> = {};
   130	  for (const [chain, address] of Object.entries(raw as Record<string, unknown>)) {
   131	    if (!CHAIN.test(chain)) {
   132	      throw new GatewayError("bad-target", `configuration chain ${JSON.stringify(chain)} is not a decimal chain id`);
   133	    }
   134	    if (typeof address !== "string" || !ADDRESS.test(address.toLowerCase())) {
   135	      throw new GatewayError(
   136	        "bad-target",
   137	        `configuration address for chain ${chain} must be 0x and 40 hex digits; got ${describe(address)}`,
