   143	  const only = chains[0];
   144	  if (only === undefined) {
   145	    throw new GatewayError("bad-target", 'configuration "contracts" must name at least one chain');
   146	  }
   147	  /* The default may be left out only when there is nothing to choose between. With two contracts a
   148	     missing default would make `/` mean whichever chain the JSON happened to list first. */
   149	  const fallback = record["default"] ?? (chains.length === 1 ? only : undefined);
   150	  if (fallback === undefined) {
   151	    throw new GatewayError("bad-target", `configuration needs "default" when it names ${chains.length} chains`);
   152	  }
   153	  if (typeof fallback !== "string" || !Object.hasOwn(contracts, fallback)) {
   154	    throw new GatewayError(
   155	      "bad-target",
   156	      `configuration "default" must be one of ${chains.join(", ")}; got ${describe(fallback)}`,
   157	    );
   158	  }
   159	  return { default: fallback, contracts };
   160	}
   161	
   162	function describe(value: unknown): string {
   163	  if (value === undefined) return "nothing";
   164	  const shown: string | undefined = JSON.stringify(value);
   165	  return shown ?? typeof value;
   166	}
   167	
   168	/**
   169	 * The target of a URL in a pinned build: always one of the configured contracts, whatever the
   170	 * hostname says, which is never read. With one contract the whole path is the resource, so a path
   171	 * of the path form is just a path. With several, the first segment is the chain and nothing else
   172	 * reaches a contract — an unconfigured first segment is a 404 that costs no call.
   173	 */
   174	export function pinnedTarget(url: URL, pins: Pins): Target {
   175	  const params: [string, string][] = [...url.searchParams.entries()];
   176	  const chains = Object.keys(pins.contracts);
   177	  const path = segments(url.pathname);
