    68	       body happened to be JSON-RPC-shaped would be believed and failover would not happen. */
    69	    if (!res.ok) throw new Error(`endpoint returned HTTP ${res.status}`);
    70	    const text = await readCapped(res, maxBytes);
    71	    const reply = JSON.parse(text) as JsonRpcReply;
    72	    if (reply.error) {
    73	      if (isRevert(reply.error)) throw new RpcRevert();
    74	      throw new Error("endpoint returned an error");
    75	    }
    76	    if (typeof reply.result !== "string") throw new Error("endpoint returned no result");
    77	    return hexToBytes(reply.result);
    78	  }
