    78	// A function replacement: a string one would expand `$&` and friends found in the minified script.
    79	const page = shell.replace("/*@boot@*/", () => boot.replaceAll("</script", "<\\/script"));
    80	
    81	await mkdir(out, { recursive: true });
    82	await Promise.all([
    83	  writeFile(`${out}/gw44-sw.js`, sw),
    84	  writeFile(`${out}/index.html`, page),
    85	  // GitHub Pages serves 404.html for unknown paths; S3 and CloudFront are pointed at index.html.
    86	  writeFile(`${out}/404.html`, page),
    87	]);
    88	/* The hashes are printed from the files on disk rather than from the strings above: what a reader
    89	   wants to reproduce is the artefact, and a hash of the value in memory would not catch a write
    90	   that changed it. Sorted by name so two runs are diffable line by line. */
    91	const names = (await readdir(out)).sort();
    92	const lines: string[] = [];
    93	const sizes = new Map<string, number>();
    94	for (const name of names) {
    95	  const bytes = await readFile(`${out}/${name}`);
    96	  sizes.set(name, bytes.length);
    97	  lines.push(`${createHash("sha256").update(bytes).digest("hex")}  ${String(bytes.length).padStart(7)}  ${name}`);
    98	}
    99	console.log(pins === null ? `built ${out}/:` : `built ${out}/ (pinned to ${listing(pins)}):`);
   100	for (const line of lines) console.log(`  ${line}`);
   101	
   102	const unexpected = names.filter((n) => !EXPECTED.includes(n));
   103	if (unexpected.length > 0) {
   104	  throw new Error(
   105	    `${out}/ holds ${unexpected.join(", ")}; the deployable is only ${EXPECTED.join(", ")}; run 'make clean'`,
   106	  );
   107	}
   108	/* The gate reads the bytes on disk, which the hash loop above already measured. `sw.length` is a
   109	   string's length in UTF-16 units and equals the byte count only while the bundler emits ASCII,
   110	   which is its default and not a thing this file asserts. */
   111	const swBytes = sizes.get("gw44-sw.js");
   112	if (swBytes === undefined) throw new Error(`${out}/ has no gw44-sw.js`);
   113	if (swBytes > SW_LIMIT) {
   114	  throw new Error(`gw44-sw.js is ${swBytes} B, over the ${SW_LIMIT} B limit`);
   115	}

